/**
 * Mini case studies, one per project: Problem -> What I built -> How it works
 * -> My contribution -> Technical challenges -> Results -> Tech. Drafted from
 * each repo (READMEs, reports, code) and fact-checked against it; every number
 * here comes from a file in that repo. Generated by work/ref/gen-studies.mjs.
 */
export type Snippet = { lang: string; code: string; note: string };
export type Study = {
  problem: string;
  built: string;
  how: string[];
  contribution: string;
  challenges: string[];
  results: string[];
  snippet?: Snippet | null;
  tech: string[];
};

